      .iter()
      .enumerate()
      .filter_map(|(i, parameter)| (!parameter.is_option()).then_some(i))
      .collect::<Vec<usize>>();

    let mut end_of_options = long.is_empty() && short.is_empty();

    let rest = self.rest();

    let mut i = 0;
    let mut positional_index = 0;
    let mut positional_accepted = 0;
